import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import type {ReactNode} from 'react';
import {View,Text,type ViewProps} from 'react-native';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {PropertyInspector} from '@/components/nyc-tron/ui/components/forge/inputs/PropertyInspector';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {useEditorBoundary} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';
import {validatePDFRect,type PDFRect} from '@/components/nyc-tron/ui/components/forge/pdf/pdf-page-model';
export interface PDFTextSelectionProps extends Omit<ViewProps,'children'>,ScopedControlProps {
 surface:ReactNode;pageId:string;selection:{text:string;start:number;end:number;rects:readonly PDFRect[];offsetUnit:'utf16'|'unicode-scalar'}|null;
 textLength:number;canCopy:boolean;copyRestriction?:string;scale:number;onCopy:(text:string,signal?:AbortSignal)=>unknown;
 onRangeCommit:(start:number,end:number,signal?:AbortSignal)=>unknown;unstyled?:boolean;
}
/** Native PDF reading order and glyph rectangles are supplied by the renderer; Unicode offsets stay explicitly typed. */
export function PDFTextSelection({scope='pdf-selection',revision=0,...props}:PDFTextSelectionProps){
 const {surface,pageId,selection,textLength,canCopy,copyRestriction,scale,onCopy:_copy,onRangeCommit:_range,unstyled=false,disabledReason,style,...rest}=props;
 if(!pageId.trim()||pageId.length>256||!Number.isSafeInteger(textLength)||textLength<0||!Number.isFinite(scale)||scale<=0||scale>100||selection&&(selection.text.length>1048576||selection.rects.length>10000||![selection.start,selection.end].every(Number.isSafeInteger)||selection.start<0||selection.end<selection.start||selection.end>textLength||!['utf16','unicode-scalar'].includes(selection.offsetUnit)))throw new RangeError('Invalid PDF text selection');selection?.rects.forEach(validatePDFRect);
 const owner=useEditorBoundary([JSON.stringify([...controlIdentity(scope,revision),pageId,disabledReason])]),guard=useScopedControl(owner,props,disabledReason!==undefined),off=guard.pending||disabledReason!==undefined;
 return <View {...rest} accessibilityLabel="PDF text selection" style={[{gap:8,minWidth:0},style]}><View style={{position:'relative'}}>{surface}{selection?.rects.map((r,index)=><View key={index} pointerEvents="none" {...{className:unstyled?undefined:'bg-accent/20'}} style={{position:'absolute',left:r.x*scale,top:r.y*scale,width:r.width*scale,height:r.height*scale}}/>)}</View>
 <Text selectable={canCopy} {...{className:unstyled?undefined:'text-text'}}>{selection?.text??'Select text using the PDF renderer'}</Text><Button title="Copy selected PDF text" disabled={off||!canCopy||!selection?.text} accessibilityHint={copyRestriction} unstyled={unstyled} onPress={()=>guard.run('copy',(h,s)=>h.canCopy&&h.selection?h.onCopy(h.selection.text,s):undefined)}/>
 {selection&&textLength>0?<PropertyInspector scope={owner} label="Reading-order selection" disabledReason={off?'Selection editing unavailable':undefined} unstyled={unstyled} fields={[{id:'start',kind:'number',label:'Selection start ('+selection.offsetUnit+')',value:selection.start,min:0,max:textLength,step:1,integer:true},{id:'end',kind:'number',label:'Selection end ('+selection.offsetUnit+')',value:selection.end,min:0,max:textLength,step:1,integer:true}]} onCommit={(id,v)=>guard.run('range',(h,s)=>{if(!h.selection||typeof v!=='number')return;return h.onRangeCommit(id==='start'?v:Math.min(v,h.selection.start),id==='end'?v:Math.max(v,h.selection.end),s);})}/>:null}<ErrorMessage message={guard.error??disabledReason??(!canCopy?copyRestriction:undefined)} unstyled={unstyled}/></View>;
}

export interface PDFPageDescriptor {id:string;label:string;width:number;height:number;rotation:0|90|180|270;canModify:boolean;groupId?:string}
export type PDFPageLayout='single'|'continuous'|'two-up'|'facing';
/** Top-left page coordinates after the host has applied crop/rotation mapping. */
export interface PDFRect {x:number;y:number;width:number;height:number}
export function validatePDFPages(pages:readonly PDFPageDescriptor[]):void{
 if(pages.length>100000||new Set(pages.map(p=>p.id)).size!==pages.length||pages.some(p=>!p.id.trim()||p.id.length>256||!p.label.trim()||p.label.length>1024||![p.width,p.height].every(n=>Number.isFinite(n)&&n>=1&&n<=14400)||![0,90,180,270].includes(p.rotation)))throw new RangeError('Invalid PDF page descriptors');
}
export function validatePDFRect(rect:PDFRect):void{if(![rect.x,rect.y,rect.width,rect.height].every(Number.isFinite)||rect.width<0||rect.height<0)throw new RangeError('Invalid PDF rectangle');}
/** One-based ranges such as 1-3, 8, 10; bounded selection metadata, not PDF processing. */
export function parsePDFPageRange(text:string,pageCount:number):number[]{
 if(!Number.isSafeInteger(pageCount)||pageCount<1||pageCount>100000||text.length>8192)throw new RangeError('Invalid PDF page range');const pages=new Set<number>();
 for(const item of text.split(',')){const match=/^\s*(\d+)\s*(?:-\s*(\d+)\s*)?$/.exec(item);if(!match)throw new Error('Use page numbers and ranges such as 1-3, 8');const a=Number(match[1]),b=Number(match[2]??match[1]);if(!Number.isSafeInteger(a)||!Number.isSafeInteger(b)||a<1||b<a||b>pageCount)throw new Error('Page range is outside this document');for(let n=a;n<=b;n++)pages.add(n-1);}
 return [...pages].sort((a,b)=>a-b);
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}
